import java.util.*;

class Solution {
    public boolean isSymmetric(TreeNode root) {
        return root == null || mirror(root.left, root.right);
    }

    private boolean mirror(TreeNode a, TreeNode b) {
        if (a == null || b == null) return a == b;   // both must be missing together
        if (a.val != b.val) return false;
        return mirror(a.left, b.right) && mirror(a.right, b.left); // outer pair, inner pair
    }
}

