function isSymmetric(root) {
  if (!root) return true;
  const q = [[root.left, root.right]];
  while (q.length) {
    const [a, b] = q.pop();
    if (!a && !b) continue;
    if (!a || !b || a.val !== b.val) return false;
    q.push([a.left, b.right], [a.right, b.left]);
  }
  return true;
}
